import { createCaregiverView } from './caregiver-view.js';
import { generateDemoVitals } from './health-demo.js';
import { renderAiChat, renderHealthOverview, appendAssistantConversation } from './overview-widgets.js';

const navItems=[['overview','◈','Overview'],['records','▤','My Health Records'],['timeline','⌁','Health Timeline'],['conflicts','⚠','Record Conflicts'],['consent','↗','Share & Consent'],['caregivers','♧','Caregiver Access'],['emergency','✚','Emergency Access'],['audit','≋','Access Audit'],['visit','▣','Visit Preparation'],['scenarios','⟡','Demo Scenarios'],['settings','⚙','Settings']];
const telugu={overview:'అవలోకనం',records:'నా ఆరోగ్య రికార్డులు',timeline:'ఆరోగ్య కాలక్రమం',conflicts:'రికార్డు విభేదాలు',consent:'భాగస్వామ్యం & సమ్మతి',caregivers:'సంరక్షకుల యాక్సెస్',emergency:'అత్యవసర యాక్సెస్',audit:'యాక్సెస్ ఆడిట్',visit:'సందర్శనకు సిద్ధత',scenarios:'డెమో దృశ్యాలు',settings:'సెట్టింగ్‌లు',newShare:'కొత్త భాగస్వామ్యం',save:'సేవ్ చేయండి',cancel:'రద్దు చేయండి',confirm:'నిర్ధారించండి',revoke:'యాక్సెస్ రద్దు చేయండి',synthetic:'కృత్రిమ డెమో డేటా',emergencyWarning:'ఇది అనుకరణ మాత్రమే. నిజమైన ఆసుపత్రి లేదా అత్యవసర సేవతో ఈ డెమో అనుసంధానించబడలేదు.',emergencyAction:'అనుకరణ అత్యవసర యాక్సెస్‌ను నిర్ధారించండి',healthOverview:'ఆరోగ్య సమీక్ష',heartRate:'హృదయ స్పందన',bloodCount:'రక్త గణన',glucose:'గ్లూకోజ్',bloodGroup:'రక్త వర్గం',healthReportsEyebrow:'కల్పిత నివేదికల నుంచి',sourceLinked:'మూల నివేదికకు అనుసంధానం',latestAvailableReport:'తాజా అందుబాటులో ఉన్న ధృవీకరించిన నివేదిక',notInAvailableReports:'అందుబాటులో ఉన్న నివేదికల్లో లేదు',valuesNotSupplied:'విలువలు అందించలేదు',noCbcReport:'CBC నివేదిక లేదు',noValueRecorded:'ఈ డెమోలో విలువ నమోదు కాలేదు',demoValues:'యాదృచ్ఛిక డెమో విలువలు',demoVitals:'కల్పిత డెమో రీడింగ్',shuffleValues:'విలువలను మార్చండి',randomDemoValue:'యాదృచ్ఛిక డెమో విలువ',bloodPressure:'రక్తపోటు',demoAssistant:'VIBA సహాయకుడు · డెమో',assistantDisclaimer:'స్థానిక స్క్రిప్ట్ చేసిన డెమో చాట్. ప్రతిస్పందనలు కల్పితం మరియు తప్పుగా ఉండవచ్చు.',chatPlaceholder:'ఒక ప్రశ్న అడగండి…',sendMessage:'పంపండి',askVitals:'రీడింగ్‌ల గురించి అడగండి',askRecords:'నివేదికల గురించి అడగండి',healthDataNote:'లేని విలువలు అందుబాటులో లేవని చూపించబడతాయి. ఎలాంటి రీడింగ్ లేదా రక్త వర్గం ఊహించబడదు. ఇది కల్పిత డెమో, వైద్య సలహా కాదు.'};
const categoryIcon={'Laboratory reports':'⌁','Prescriptions':'℞','Consultation notes':'▤','Imaging reports':'◉','Discharge summaries':'▣','Vaccination records':'✳'};
const scenarios=[
  ['patient-onboarding','◉','Patient Onboarding','Explore the fictional patient profile and seeded record library.'],
  ['conflicting-labs','⌁','Conflicting Lab Reports','Compare inconsistent dates, retain both records, and request source verification.'],
  ['uncertain-ocr','✎','Uncertain Prescription OCR','Request human review while leaving the handwritten dosage unconfirmed.'],
  ['seven-day-share','↗','Seven-Day Specialist Share','Create a scoped seven-day share, inspect recipient access, then revoke it.'],
  ['caregiver-boundary','♧','Caregiver Permission Boundary','Try an action outside the caregiver’s active scope and inspect the denial.'],
  ['emergency-break-glass','✚','Emergency Break-Glass','Block an unlisted actor and grant a limited, simulated emergency window.'],
  ['provider-correction','⟲','Provider Correction After Sharing','Preserve the original, create a correction assertion, and inspect affected shares.'],
  ['service-outage','◌','Service Outage','Trigger a simulated timeout and retry without losing the demo data.'],
  ['stale-data','◷','Stale Data','Show a freshness warning and refresh the synthetic snapshot.'],
  ['conflicting-update','⇄','Conflicting Update','Hold two edits for explicit review without overwriting the source record.'],
];
const state={view:'overview',language:'en',profile:null,records:[],providers:[],grants:[],caregivers:[],conflicts:[],notifications:[],edgeCases:[],dashboard:null,freshness:null,demoState:{},demoVitals:generateDemoVitals(),aiChatMessages:[{role:'assistant',text:'Hi! Ask me about the demo readings, reports, or sharing.'}],filters:{search:'',category:'',provider:'',sort:'newest'},page:1,pageSize:6,globalQuery:'',scenarioResults:{},selectedProvider:'',reducedMotion:false,force2d:false,caregiverSelection:'CG-01',visitSelection:new Set(),visitDraft:'',auditSearch:'',recordSearch:'',currentEmergency:null,testResults:null,sceneCleanup:null};
const main=document.querySelector('#mainContent'), modalRoot=document.querySelector('#modalRoot');
const escapeHtml=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(key,english)=>state.language==='te'?(telugu[key]||english):english;
const date=(v,options={year:'numeric',month:'short',day:'numeric'})=>{if(!v)return '—';const d=new Date(v.length===10?`${v}T12:00:00`:v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString(state.language==='te'?'te-IN':'en-IN',options)};
const relative=(v)=>{const d=Date.now()-new Date(v).getTime();if(d<60000)return 'Just now';if(d<3600000)return `${Math.floor(d/60000)} min ago`;if(d<86400000)return `${Math.floor(d/3600000)} hr ago`;return date(v)};
const badge=(label,tone='')=>`<span class="badge ${tone?`badge-${tone}`:''}">${escapeHtml(label)}</span>`;
const categoryOptions=['Laboratory reports','Prescriptions','Consultation notes','Imaging reports','Discharge summaries','Vaccination records'];

async function api(path,options={}){const res=await fetch(path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});let json;try{json=await res.json()}catch{throw {message:'The local mock service returned an unreadable response.'}}if(!res.ok||json.success===false)throw json.error||{message:'The request could not be completed.'};return json.data;}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.innerHTML=`<span class="toast-icon">${type==='error'?'!':'✓'}</span><span>${escapeHtml(message)}</span>`;document.querySelector('#toastRegion').append(el);document.querySelector('#announcer').textContent=message;setTimeout(()=>el.remove(),4500)}
function formatError(error){return error?.message||String(error||'Something went wrong.')}
function navRender(){const nav=document.querySelector('#primaryNav');nav.innerHTML=navItems.filter(([id])=>id!=='settings').map(([id,icon,label])=>`<button class="nav-item ${state.view===id?'active':''}" data-nav="${id}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span data-i18n="nav.${id}">${t(id,label)}</span>${id==='conflicts'&&state.conflicts.length?`<span class="nav-count">${state.conflicts.length}</span>`:''}</button>`).join('');document.querySelectorAll('[data-i18n="nav.settings"]').forEach(el=>el.textContent=t('settings','Settings'));}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${escapeHtml(eyebrow)}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>${state.view==='consent'?activeShareSummary():state.view==='settings'?profileSettingsCard():''}`}
function caregiversView(){return createCaregiverView(state,escapeHtml,categoryOptions,date)}
function titleForView(){return navItems.find(x=>x[0]===state.view)?.[2]||'Overview'}
function render(){if(state.sceneCleanup){state.sceneCleanup();state.sceneCleanup=null;}navRender();document.querySelector('#pageCrumb').textContent=t(state.view,titleForView());document.documentElement.lang=state.language==='te'?'te':'en';document.body.classList.toggle('no-motion',state.reducedMotion);document.documentElement.dataset.reducedMotion=String(state.reducedMotion);main.innerHTML=({overview:overviewView,records:recordsView,timeline:timelineView,conflicts:conflictsView,consent:consentView,caregivers:caregiversView,emergency:emergencyView,audit:auditView,visit:visitView,scenarios:scenariosView,settings:settingsView}[state.view]||overviewView)();bindScene();if(state.view==='audit')loadAudit(false);}
function navigate(view){state.view=view;state.page=1;document.querySelector('#sidebar').classList.remove('mobile-open');render();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:state.reducedMotion?'instant':'smooth'});}
function eventIcon(action){return ({CONSENT_CREATED:'↗',CONSENT_REVOKED:'⨯',RECORD_CREATED:'+',METADATA_CORRECTED:'✎',CORRECTION_CREATED:'⟲',RECIPIENT_READ:'◉',BREAK_GLASS_GRANTED:'✚',BREAK_GLASS_ATTEMPT:'!',CAREGIVER_GRANT_CREATED:'♧',CAREGIVER_GRANT_REVOKED:'⨯'})[action]||'·'}
function overviewView(){const d=state.dashboard||{totalRecords:state.records.length,providers:state.providers.length,activeConsents:state.grants.filter(x=>x.status==='active').length,conflicts:state.conflicts.length,expiringShares:0,recentEvents:[],records:[],providersList:state.providers,notices:state.notifications,stale:state.demoState.stale};const kpis=[['▤','Synthetic records',d.totalRecords,'Across your record library','records'],['⌖','Connected providers',d.providers,'Fictional sources only','records'],['↗','Active consents',d.activeConsents,'Scoped access grants','consent'],['⚠','Date & metadata flags',d.conflicts,'Human review requested','conflicts'],['◷','Expiring shares',d.expiringShares,'Within the next 48 hours','consent']];return `${heading('YOUR HEALTH, IN ONE PLACE','A clearer view of your health journey','Your records stay yours. Review what you have, understand who can see it, and decide what happens next.',`<button class="btn btn-primary" data-nav="consent"><span class="icon-text">＋</span>${t('newShare','Share a record')}</button>`)}${d.stale?`<div class="alert-strip"><span class="alert-icon">◷</span><div><strong>Demo snapshot may be stale</strong><span>Last refreshed ${date(state.freshness?.lastRefreshed)}. Review freshness before relying on a source display.</span></div><button class="btn btn-sm" data-action="refresh-demo">Refresh</button></div>`:''}<section class="kpi-grid">${kpis.map(([icon,label,value,foot,route],i)=>`<button class="card kpi ${i===3&&value?'kpi-warn':''}" data-nav="${route}" aria-label="${label}: ${value}. Open ${route}"><div class="kpi-label"><span>${icon}</span>${label}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></button>`).join('')}</section><div class="overview-grid"><section class="card scene-card"><div class="card-header scene-head"><div><h2>Your health ecosystem</h2><p>Move the model · choose a connected record</p></div><select class="filter-select" id="providerSceneFilter" aria-label="Highlight provider"><option value="">All providers</option>${state.providers.map(p=>`<option value="${escapeHtml(p.name)}" ${state.selectedProvider===p.name?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="scene-wrap" id="sceneWrap"><div class="scene-glow"></div><span class="scene-label scene-label-left"><strong>Connected records</strong>${state.records.length} synthetic entries</span><span class="scene-label scene-label-right"><strong>Patient-controlled</strong>Consent at every step</span><canvas id="healthScene" tabindex="0" aria-label="Interactive 3D synthetic health model. Drag to rotate and select record hotspots."></canvas><div class="scene-fallback" id="sceneFallback"><div class="body-outline"><svg class="anatomy-silhouette" viewBox="0 0 120 250" aria-hidden="true"><defs><linearGradient id="skinTone" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f3b1a6"/><stop offset=".52" stop-color="#df8890"/><stop offset="1" stop-color="#b45c71"/></linearGradient></defs><g fill="url(#skinTone)" stroke="#a84f64" stroke-width="1.2" stroke-linejoin="round"><ellipse cx="60" cy="21" rx="14" ry="18"/><path d="M53 36h14l3 10q13 2 20 11l14 26-8 7-10-7-8-15-2 36q0 10 5 20l-7 14H46l-7-14q5-10 5-20l-2-36-8 15-10 7-8-7 14-26q7-9 20-11z"/><path d="M47 137q-5 12-5 25l-1 48-5 13-2 6h20l4-12 2-38h1l3 38 4 12h20l-2-6-5-13-2-48q0-13-5-25z"/><path d="M53 35q7 4 14 0l-1 10H54z"/></g><g fill="none" stroke="#f9c7bd" stroke-width="1.5" stroke-linecap="round" opacity=".9"><path d="M34 57q7 5 14 4m24-4q7 1 14-4M47 57q13 8 26 0M60 61v38M48 70q5-3 10 0m4 0q5-3 10 0M48 79q5-3 10 0m4 0q5-3 10 0M48 88q5-3 10 0m4 0q5-3 10 0M44 108q16 8 32 0M44 150q8 7 15 6m2 0q8 1 15-6M44 166l11 5m21-5-11 5M43 187q7 8 13 6m21-6q-7 8-13 6"/></g><path d="M57 66c-8-7-13 4 3 15 16-11 11-22 3-15l-3 3z" fill="#bb4f67" stroke="#fff0e9" stroke-width="1"/><circle cx="55" cy="20" r="1.2" fill="#85465c"/><circle cx="65" cy="20" r="1.2" fill="#85465c"/></svg><button class="fallback-node" data-record="HV-LAB-1042" aria-label="Open lipid panel"></button><button class="fallback-node" data-record="HV-RX-2071" aria-label="Open prescription sample"></button><button class="fallback-node" data-record="HV-IMG-4185" aria-label="Open imaging report"></button></div><span class="subtle-note">2D accessible anatomy map · select a record point</span></div><span class="scene-caption">3D MODEL · SYNTHETIC DATA ONLY</span><span class="scene-prompt">Select a glowing point ↗</span></div><div class="network-preview">${state.providers.slice(0,4).map((p,i)=>`<button class="network-provider link-button" data-action="provider-select" data-provider="${escapeHtml(p.name)}"><i class="provider-dot ${['','blue','gold','purple'][i]}"></i><span>${escapeHtml(p.name)}</span></button>`).join('')}</div></section><div class="overview-side-stack">${renderAiChat(state,t,escapeHtml)}<section class="card"><div class="card-header"><div><h2>Recent activity</h2><p>Changes and access in your demo space</p></div><button class="link-button" data-nav="audit">View audit →</button></div><div class="card-body activity-list">${d.recentEvents.length?d.recentEvents.map(ev=>`<div class="activity-item" data-nav="audit" role="button" tabindex="0"><span class="activity-marker">${eventIcon(ev.action)}</span><span class="activity-copy"><strong>${escapeHtml(ev.action.replaceAll('_',' ').toLowerCase())}</strong><small>${escapeHtml(ev.reason||ev.resource)} · ${escapeHtml(ev.outcome)}</small></span><span class="activity-time">${relative(ev.timestamp)}</span></div>`).join(''):`<div class="empty-state"><strong>No recent activity</strong>Your simulated access events will appear here.</div>`}</div></section></div></div>${healthOverviewView()}<div class="content-grid"><section class="card"><div class="card-header"><div><h2>Health timeline</h2><p>Three dates, clearly separated</p></div><button class="link-button" data-nav="timeline">Full timeline →</button></div><div class="card-body"><div class="timeline-mini">${d.records.slice(0,4).map(r=>`<div class="timeline-mini-item" data-record="${r.id}" role="button" tabindex="0"><i class="timeline-dot"></i><div class="timeline-mini-copy"><strong>${escapeHtml(r.title)}</strong><small>${date(r.eventDate)} · ${escapeHtml(r.provider)}</small></div></div>`).join('')}</div></div></section><section class="card"><div class="card-header"><div><h2>Needs your attention</h2><p>Review source details before deciding</p></div><span class="badge badge-amber">${state.conflicts.length} open</span></div><div class="card-body">${state.conflicts.slice(0,2).map(c=>`<div class="activity-item" data-nav="conflicts" role="button" tabindex="0"><span class="activity-marker" style="color:#edc67e;background:rgba(153,112,42,.12)">⚠</span><span class="activity-copy"><strong>${escapeHtml(c.type)}</strong><small>${escapeHtml(c.why)}</small></span></div>`).join('')||`<div class="empty-state"><strong>No open flags</strong>Source records remain available for review.</div>`}</div></section></div>`}

function healthOverviewView(){return renderHealthOverview(state,t,escapeHtml,date);}
function recordRow(r){const icon=categoryIcon[r.category]||'▤';const conflict=r.conflicts?.length?badge(r.verification==='Needs review'?'Needs review':'Flagged','amber'):badge(r.verification==='Source verified'?'Verified':'Patient supplied','teal');return `<div class="record-row" data-record="${r.id}" role="button" tabindex="0" aria-label="Open ${escapeHtml(r.title)}"><span class="record-icon">${icon}</span><span class="record-name"><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.id)} · ${escapeHtml(r.category)}</small></span><span class="record-cell">${escapeHtml(r.provider||'Provider missing')}<small>${escapeHtml(r.location||'Location missing')}</small></span><span class="record-cell">${date(r.eventDate)}<small>Event date</small></span><span class="record-cell">${conflict}</span><span class="record-row-actions"><button class="btn btn-sm" data-record-edit="${r.id}" aria-label="Edit ${escapeHtml(r.title)}"><span class="icon-text">✎</span>Edit</button></span></div>`}
function recordsView(){const filtered=(state.serverRecordResults||state.records).filter(r=>(!state.filters.search||`${r.title} ${r.provider} ${r.id} ${r.values}`.toLowerCase().includes(state.filters.search.toLowerCase()))&&(!state.filters.category||r.category===state.filters.category)&&(!state.filters.provider||r.provider===state.filters.provider)).sort((a,b)=>(state.filters.sort==='oldest'?1:-1)*a.eventDate.localeCompare(b.eventDate));const pages=Math.max(1,Math.ceil(filtered.length/state.pageSize));state.page=Math.min(state.page,pages);const visible=filtered.slice((state.page-1)*state.pageSize,state.page*state.pageSize);return `${heading('YOUR RECORD LIBRARY','My health records','Search, sort, and review records from your fictional providers. Original source information remains preserved when you add a correction.',`<button class="btn btn-primary" data-action="new-record"><span class="icon-text">＋</span>Add synthetic record</button>`)}<div class="toolbar"><input class="filter-input" id="recordSearch" placeholder="Search title, ID, provider…" value="${escapeHtml(state.filters.search)}" aria-label="Search records"><select id="recordCategory" class="filter-select" aria-label="Filter by record category"><option value="">All categories</option>${categoryOptions.map(c=>`<option ${state.filters.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="recordProvider" class="filter-select" aria-label="Filter by provider"><option value="">All providers</option>${[...new Set(state.records.map(x=>x.provider).filter(Boolean))].map(p=>`<option ${state.filters.provider===p?'selected':''}>${escapeHtml(p)}</option>`).join('')}</select><select id="recordSort" class="filter-select" aria-label="Sort records"><option value="newest" ${state.filters.sort==='newest'?'selected':''}>Newest event</option><option value="oldest" ${state.filters.sort==='oldest'?'selected':''}>Oldest event</option></select><button class="btn btn-quiet" data-action="clear-record-filters">Clear filters</button></div><section class="card"><div class="table-head"><span></span><span>Record</span><span>Provider & location</span><span>Event date</span><span>Verification</span><span></span></div><div class="record-list">${visible.map(recordRow).join('')||`<div class="empty-state"><strong>No matching records</strong>Try a different category, provider, or search phrase.</div>`}</div><div class="pagination"><span>${filtered.length?`${(state.page-1)*state.pageSize+1}–${Math.min(state.page*state.pageSize,filtered.length)} of ${filtered.length} records`:'0 records'}</span><div class="pagination-controls"><button data-action="page-prev" ${state.page<=1?'disabled':''}>←</button><span>${state.page} / ${pages}</span><button data-action="page-next" ${state.page>=pages?'disabled':''}>→</button></div></div></section><p class="subtle-note" style="margin-top:12px">Record dates are shown as supplied by the fictional source. Upload date and report date remain available in each record’s details.</p>`}

function timelineView(){const providers=[...new Set(state.records.map(x=>x.provider).filter(Boolean))];const records=(state.timelineResults||state.records.map(record=>({record}))).map(x=>x.record).filter(r=>!state.filters.provider||r.provider===state.filters.provider).sort((a,b)=>b.eventDate.localeCompare(a.eventDate));return `${heading('THREE DATES, ONE STORY','Health timeline','See when an event occurred, when its report was issued, and when that report was uploaded. Dates stay attributed to their source.',`<button class="btn" data-nav="conflicts">Review date flags</button>`)}<div class="toolbar"><select id="timelineProvider" class="filter-select" aria-label="Filter timeline by provider"><option value="">All providers</option>${providers.map(p=>`<option ${state.filters.provider===p?'selected':''}>${escapeHtml(p)}</option>`).join('')}</select><select id="timelineCategory" class="filter-select" aria-label="Filter timeline by category"><option value="">All categories</option>${categoryOptions.map(c=>`<option ${state.filters.category===c?'selected':''}>${c}</option>`).join('')}</select><button class="btn btn-quiet" data-action="clear-timeline-filters">Clear filters</button><span class="status-line">${records.length} synthetic events · Source provider shown on every entry</span></div><div class="split-layout"><section class="card"><div class="card-header"><div><h2>Chronological records</h2><p>Sorted by event date · each date remains distinct</p></div></div><div class="card-body timeline-list">${records.filter(r=>!state.filters.category||r.category===state.filters.category).map(r=>`<article class="timeline-event" data-record="${r.id}" tabindex="0"><div class="timeline-event-top"><div><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.provider||'Provider not supplied')} · ${escapeHtml(r.location||'Location missing')}</p></div>${r.conflicts?.length?badge('Review source','amber'):badge('Source recorded','teal')}</div><div class="date-pills"><div class="date-pill"><small>Event occurred</small><strong>${date(r.eventDate)}</strong></div><div class="date-pill"><small>Report issued</small><strong>${date(r.reportDate)}</strong></div><div class="date-pill"><small>Uploaded</small><strong>${date(r.uploadDate)}</strong></div></div><div class="subtle-note" style="margin-top:10px">Source: ${escapeHtml(r.source)} · <button class="link-button" data-record="${r.id}">Open source details →</button></div></article>`).join('')||`<div class="empty-state"><strong>No timeline entries</strong>Adjust the selected filters.</div>`}</div></section><aside class="card"><div class="card-header"><div><h2>Compare flagged lab reports</h2><p>Review evidence side by side</p></div></div><div class="card-body">${state.conflicts.filter(c=>c.id==='CF-DATE-01').map(c=>`<div class="compare-grid">${c.values.map(v=>{const r=state.records.find(x=>x.id===v.recordId);return `<div class="compare-side"><small>${escapeHtml(r?.source||'Source')} · event date</small><strong>${date(v.value)}</strong><span>${escapeHtml(r?.title||v.recordId)}</span></div>`}).join('')}</div><p class="subtle-note">${escapeHtml(c.why)}</p><div class="warning-box">This comparison identifies a mismatch, not the correct date. Keep both entries until a human verifies the source.</div><button class="btn btn-sm" style="margin-top:10px" data-nav="conflicts">Open conflict review</button>`).join('')||`<p class="subtle-note">No date mismatch is currently flagged.</p>`}</div></aside></div>`}

function conflictsView(){return `${heading('SOURCE REVIEW','Record conflicts','The demo detects differences and uncertainty. It does not decide which source is correct, infer uncertain dosage, or merge records.',`<button class="btn" data-action="refresh-conflicts">↻ Refresh flags</button>`)}${state.conflicts.map(c=>`<article class="card conflict-card"><div class="conflict-top"><span class="conflict-symbol">⚠</span><div><h3>${escapeHtml(c.type)}</h3><p>${escapeHtml(c.why)}</p></div>${badge(c.confidence,'amber')}</div><div class="compare-grid">${c.values.map(v=>{const r=state.records.find(x=>x.id===v.recordId);return `<div class="compare-side"><small>${escapeHtml(v.source)} · ${escapeHtml(v.recordId)}</small><strong>${escapeHtml(v.value)}</strong><span>${escapeHtml(r?.title||'Synthetic record')}</span></div>`}).join('')}</div><div class="conflict-evidence"><strong>Origin:</strong> ${escapeHtml(c.origin)} &nbsp;·&nbsp; <strong>Freshness:</strong> ${escapeHtml(c.freshness)}<br><strong>Suggested check:</strong> Compare the original source document, confirm with its author, and record a human assertion with the reason. No source is silently overwritten.</div><div class="conflict-actions"><button class="btn btn-sm" data-action="open-conflict-source" data-record="${escapeHtml(c.records[0])}">Review source record</button>${c.id==='CF-DATE-01'?`<button class="btn btn-sm" data-action="conflict-retain">Retain both pending verification</button><button class="btn btn-sm" data-action="conflict-link">Link as possible duplicate</button><button class="btn btn-sm btn-primary" data-action="open-correction" data-record="HV-LAB-1098">Record a correction assertion</button>`:''}${c.id==='CF-OCR-01'?`<button class="btn btn-sm btn-primary" data-action="verify-ocr">Request human verification</button><button class="btn btn-sm" data-record="HV-RX-2071">Open original scan details</button>`:''}${c.id==='CF-META-01'?`<button class="btn btn-sm" data-record="${escapeHtml(c.records[0])}">Review source record</button><button class="btn btn-sm btn-primary" data-action="open-correction" data-record="${escapeHtml(c.records[0])}">Add metadata assertion</button>`:''}</div></article>`).join('')||`<section class="card empty-state"><strong>No open conflicts</strong>Resolved flags remain in each record’s history and the append-only audit ledger.</section>`}<section class="card" style="padding:13px 15px"><div class="inline-actions">${badge('Deterministic mock detection','blue')}<span class="subtle-note">Date mismatch · near duplicate · missing metadata · uncertain OCR · provider mismatch · superseded record</span></div></section>`}

function shareCard(g){const current=g.status==='active'&&new Date(g.expiresAt)<=Date.now()?'expired':g.status;return `<article class="card grant-card"><div class="grant-head"><div><h3>${escapeHtml(g.recipient)}</h3><small>Created ${date(g.createdAt)} · Purpose: ${escapeHtml(g.purpose)}</small></div>${badge(current,current==='active'?'teal':current==='revoked'?'red':'amber')}</div><div class="grant-meta"><span>Selected records: ${g.recordIds.length}</span><span>Categories: ${g.categories.length||'None'}</span><span>Expires ${date(g.expiresAt)}</span>${current==='active'?`<span>${shareTimeRemaining(g)}</span>`:''}<span>${escapeHtml(g.id)}</span></div><div class="grant-actions"><button class="btn btn-sm" data-action="recipient-view" data-grant="${escapeHtml(g.id)}">Recipient view</button>${current==='active'?`<button class="btn btn-sm btn-danger" data-action="revoke-share" data-grant="${escapeHtml(g.id)}">${t('revoke','Cancel access')}</button>`:''}<span class="subtle-note">Simulated only · no provider received this data</span></div></article>`}
function consentView(){const active=state.grants.filter(g=>g.status==='active').length;return `${heading('YOU CHOOSE WHAT LEAVES','Share & consent','Select an exact scope, purpose, and expiry. Preview the fictional recipient’s view before creating a simulated grant.',`<span class="badge badge-teal">${active} active grant${active===1?'':'s'}</span>`)}<div class="consent-layout"><section><div class="card" style="padding:16px 17px"><div class="step-indicator"><div class="step active"><span>1</span> Choose scope</div><i class="step-line"></i><div class="step active"><span>2</span> Review preview</div><i class="step-line"></i><div class="step"><span>3</span> Confirm share</div></div><form id="shareForm"><div class="form-grid"><div class="field"><label for="shareRecipient">Fictional recipient</label><select id="shareRecipient" name="recipient" required><option value="">Choose a recipient</option><option>Dr. Asha Menon · Endocrinology (fictional)</option><option>Dr. Meera Rao · Lotus Care Centre (fictional)</option><option>Harbor Diagnostics · Records desk (fictional)</option></select></div><div class="field"><label for="sharePurpose">Purpose of sharing</label><input id="sharePurpose" name="purpose" placeholder="e.g. Specialist consultation preparation" required maxlength="120"></div><div class="field"><label for="shareExpiry">Access expires after</label><select id="shareExpiry" name="expirationDays"><option value="1">1 day</option><option value="7" selected>7 days</option><option value="14">14 days</option><option value="30">30 days</option><option value="90">90 days</option></select></div><div class="field"><label for="shareType">Recipient type</label><select id="shareType" name="recipientType"><option>Specialist</option><option>Primary care</option><option>Diagnostic center</option><option>Other fictional recipient</option></select></div><div class="field span-2"><span class="field-label">Choose individual records</span><div class="selectable-list">${state.records.map(r=>`<label class="selectable-row"><input type="checkbox" name="recordIds" value="${r.id}" data-share-item><div><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.id)} · ${escapeHtml(r.provider)} · ${date(r.eventDate)}</small></div>${badge(r.category,'blue')}</label>`).join('')}</div></div><div class="field span-2"><span class="field-label">Or include a record category</span><div class="checkbox-list" style="display:grid;grid-template-columns:1fr 1fr">${categoryOptions.map(c=>`<label class="checkbox-option"><input type="checkbox" name="categories" value="${escapeHtml(c)}" data-share-item>${escapeHtml(c)}</label>`).join('')}</div></div><div class="field span-2"><div class="consent-note" lang="${state.language==='te'?'te':'en'}">${state.language==='te'?'ఈ డెమోలో భాగస్వామ్యం పూర్తిగా అనుకరణ మాత్రమే. ఎంపిక చేసిన రికార్డులు, ప్రయోజనం, గడువు మాత్రమే అనుమతించబడతాయి. రద్దు చేసిన తర్వాతి అనుకరణ యాక్సెస్ నిరోధించబడుతుంది. ఇప్పటికే డౌన్‌లోడ్ చేసిన కాపీలను వెనక్కి తీసుకోలేము.':'This is a simulated share. Access is limited to the records, purpose, and expiry you select. Later simulated access is blocked after revocation. A revocation cannot guarantee deletion of copies already downloaded by a recipient.'}</div></div></div><div class="inline-actions" style="justify-content:flex-end;margin-top:14px"><button type="reset" class="btn btn-quiet">Clear draft</button><button class="btn btn-primary" type="submit">${t('confirm','Review & create simulated share')} <span>→</span></button></div></form></div><div class="section-title"><div><h2>Active and past shares</h2><p>Each receipt shows the actual mock permission state.</p></div></div>${state.grants.slice().reverse().map(shareCard).join('')||`<div class="card empty-state"><strong>No shares created</strong>Use the form to build a scoped demo share.</div>`}</section><aside class="card consent-preview"><div class="card-header"><div><h2>Recipient preview</h2><p>Changes as you select records</p></div>${badge('PREVIEW','blue')}</div><div class="preview-document" id="sharePreview"><div class="doc-brand">VIBA · ABHA redefined....! · SYNTHETIC DEMO</div><h3>Shared health records</h3><p>Recipient: <strong id="previewRecipient">Not selected</strong><br>Purpose: <span id="previewPurpose">Not selected</span><br>Access until: <span id="previewExpiry">7 days from confirmation</span></p><ul id="previewRecords"><li>Choose one or more records to preview.</li></ul><p class="preview-legal">Simulated recipient view only. This interface does not send or upload records. The recipient’s scope is enforced by the local mock API.</p></div><div class="card-body" style="padding-top:0"><p class="consent-copy">Review each item before confirming. The mock API will return only the selected record IDs or categories. Sensitive notes are never included unless you select them.</p></div></aside></div>`}

function shareTimeRemaining(grant){const ms=Date.parse(grant.expiresAt)-Date.now();if(ms<=0)return 'Expired';const days=Math.ceil(ms/86400000);return `${days} day${days===1?'':'s'} remaining`}
function activeShareSummary(){const active=state.grants.filter(g=>g.status==='active'&&Date.parse(g.expiresAt)>Date.now());if(!active.length)return '';return `<section class="card" aria-label="Your active shares" style="padding:14px 16px;margin:0 0 14px;border-color:rgba(236,132,148,.28)"><div class="card-header" style="padding:0 0 10px"><div><h2>Active access</h2><p>Cancel a share at any time to block future simulated access.</p></div><span class="badge badge-teal">${active.length} active</span></div>${active.map(g=>`<div class="inline-actions" style="justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid var(--line)"><div><strong style="display:block;color:#e0eced;font-size:10px">${escapeHtml(g.recipient)}</strong><small class="subtle-note">${escapeHtml(g.purpose)} · ${shareTimeRemaining(g)} · Expires ${date(g.expiresAt)}</small></div><button class="btn btn-danger" data-action="revoke-share" data-grant="${escapeHtml(g.id)}">${t('revoke','Cancel access now')}</button></div>`).join('')}<p class="subtle-note" style="margin:7px 0 0">Revocation blocks later demo access. Copies already downloaded cannot be recalled.</p></section>`}
function profileSettingsCard(){const p=state.profile||{};return `<section class="card" style="margin:0 0 14px"><div class="card-header"><div><h2>Profile details</h2><p>Update the fictional details shown in your patient space.</p></div></div><div class="card-body"><form id="profileForm" class="form-grid"><div class="field"><label for="profileFullName">Full name</label><input id="profileFullName" name="name" value="${escapeHtml(p.name||'')}" required maxlength="80" autocomplete="name"></div><div class="field"><label for="profileDateOfBirth">Date of birth</label><input id="profileDateOfBirth" name="dateOfBirth" type="date" value="${escapeHtml(p.dateOfBirth||'')}" autocomplete="bday"></div><div class="field"><label for="profileEmail">Email address</label><input id="profileEmail" name="email" type="email" value="${escapeHtml(p.email||'')}" maxlength="120" autocomplete="email"></div><div class="field"><label for="profilePhone">Phone number</label><input id="profilePhone" name="phone" type="tel" value="${escapeHtml(p.phone||'')}" maxlength="24" autocomplete="tel"></div><div class="field span-2"><div class="warning-box">This prototype saves profile edits only in its local, fictional demo state. Do not enter real personal or health information. Changes may reset when this browser session ends or the demo server restarts.</div></div><div class="field span-2" style="display:flex;justify-content:flex-end"><button class="btn btn-primary" type="submit">Save profile details</button></div></form></div></section>`}
function profileInitials(name){return String(name||'Demo patient').trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()||'SR'}
function syncProfileChrome(profile=state.profile){if(!profile)return;const initials=profileInitials(profile.name);for(const [id,value] of [['profileName',profile.name],['sidebarProfileName',profile.name],['profileAvatar',initials],['sidebarProfileAvatar',initials]]){const el=document.getElementById(id);if(el)el.textContent=value}}
const profileSessionKey='healthverse-profile-session';
function readSessionProfile(){try{return JSON.parse(sessionStorage.getItem(profileSessionKey)||'null')}catch{return null}}
async function saveProfileDetails(payload){try{const profile=await api('/api/profile',{method:'PATCH',body:JSON.stringify(payload)});sessionStorage.removeItem(profileSessionKey);return {profile,localOnly:false}}catch(error){if(error.code!=='NOT_FOUND')throw error;const profile={...state.profile,...payload};sessionStorage.setItem(profileSessionKey,JSON.stringify(profile));return {profile,localOnly:true}}}
function caregiverView(){return createCaregiverView(state,escapeHtml,categoryOptions,date)}
function emergencyView(){const active=state.currentEmergency?.status==='active'&&new Date(state.currentEmergency.expiresAt)>Date.now();const warning=state.language==='te'?telugu.emergencyWarning:'This break-glass workflow is a local demonstration. It is not connected to a hospital, emergency service, or real patient record.';return `${heading('LIMITED, TRACEABLE, SIMULATED','Emergency access',warning,`<span class="badge badge-amber">SIMULATED ONLY</span>`)}<div class="split-layout"><section class="card"><div class="card-header"><div><h2>Break-glass request</h2><p>Requires an authorized fictional actor, a reason, and explicit confirmation</p></div></div><div class="card-body">${active?`<div class="alert-strip"><span class="alert-icon">✚</span><div><strong>Simulated emergency grant is active</strong><span>${escapeHtml(state.currentEmergency.actor)} · expires ${date(state.currentEmergency.expiresAt,{hour:'2-digit',minute:'2-digit'})}</span></div><button class="btn btn-danger btn-sm" data-action="revoke-emergency" data-grant="${state.currentEmergency.id}">Revoke</button></div>`:''}<form id="emergencyForm"><div class="field"><label for="emergencyActor">Fictional hospital user</label><select id="emergencyActor" name="actor" required><option value="">Choose an authorized actor</option><option>Dr. Leela Nair · Cityline Hospital (fictional)</option><option>Dr. Arjun Das · Cityline Hospital (fictional)</option><option>Unlisted clinician · fictional</option></select></div><div class="field" style="margin-top:12px"><label for="emergencyReason">Specific emergency justification</label><textarea id="emergencyReason" name="justification" minlength="18" maxlength="400" placeholder="Explain why ordinary consent is unavailable and why this limited access is needed." required></textarea><small class="field-help">This text becomes part of the append-only demo audit event.</small></div><label class="selectable-row" style="margin-top:12px"><input type="checkbox" name="confirmed" required><div><strong>I understand this creates a simulated, time-limited access event.</strong><small>No real emergency service is contacted. Selected scope expires after 60 minutes unless revoked sooner.</small></div></label><button class="btn btn-primary" style="margin-top:14px" type="submit">${t('emergencyAction','Confirm simulated emergency access')}</button></form></div></section><aside class="card"><div class="card-header"><div><h2>What the demo grants</h2><p>Ordinary consent and emergency access stay distinct</p></div></div><div class="card-body"><div class="warning-box" style="margin-bottom:12px">${state.language==='te'?telugu.emergencyWarning:'Emergency access is simulated. No real hospital or emergency service is connected. The actor, reason, time, outcome, and limited scope are recorded.'}</div><div class="pill-list"><span class="pill">Emergency summary</span><span class="pill">Synthetic allergy field</span><span class="pill">Selected recent records</span><span class="pill">60-minute limit</span></div><div class="divider"></div><div class="subtle-note">Authorized demo identities</div><p class="tiny" style="color:#c5d8da;line-height:1.8">Dr. Leela Nair · Cityline Hospital<br>Dr. Arjun Das · Cityline Hospital</p><div class="divider"></div><div class="inline-actions">${badge('Audit logged','teal')}${badge('Patient notification simulated','blue')}</div></div></aside></div>`}

function auditView(){const events=state.dashboard?.recentEvents;return `${heading('TRANSPARENT BY DEFAULT','Access audit','Chronological, append-only demo events show who did what, what resource was affected, and whether access succeeded.',`<button class="btn" data-action="audit-check">⛨ Verify hash chain</button>`)}<div class="toolbar"><input class="filter-input" id="auditSearch" value="${escapeHtml(state.auditSearch)}" placeholder="Search actor, action, resource…" aria-label="Search audit events"><button class="btn btn-quiet" data-action="audit-clear">Clear search</button><span class="integrity-status" id="integrityStatus">Hash chain ready for verification</span></div><section class="card"><div class="card-header"><div><h2>Event ledger</h2><p>Browser-only demo log · not a secure production audit system</p></div><span class="badge badge-blue" id="auditCount">${state.dashboard?.recentEvents?.length||state.conflicts.length} recent</span></div><div class="card-body audit-list" id="auditList"><div class="loading-state" style="min-height:120px">Loading audit entries…</div></div></section><p class="subtle-note" style="margin-top:11px">Each entry is linked to the preceding event with a SHA-256 hash. This demonstrates tamper detection only; a local browser demo is not a protected healthcare audit service.</p>`}

function buildVisitSummary(){const selected=state.records.filter(r=>state.visitSelection.has(r.id));if(!selected.length)return 'Select one or more records to prepare a factual summary.';const lines=[`VIBA · ABHA redefined....! · SYNTHETIC DEMO VISIT SUMMARY`,`Prepared ${new Date().toLocaleString()} · Fictional patient: Samira Reddy`,``,`SELECTED SOURCE RECORDS`];for(const r of selected){lines.push(`• ${r.title} (${r.id})`);lines.push(`  Event: ${r.eventDate} · Report issued: ${r.reportDate} · Uploaded: ${r.uploadDate}`);lines.push(`  Provider: ${r.provider||'Not supplied'} · Source: ${r.source}`);lines.push(`  Source-reported text: ${r.values}`);if(r.conflicts?.length)lines.push(`  Requires verification: ${r.conflicts.join('; ')}`);if(r.ocr&&!r.ocr.verified)lines.push(`  Uncertain OCR: “${r.ocr.text}” (${Math.round(r.ocr.confidence*100)}% confidence); not confirmed.`);lines.push('');}lines.push('QUESTIONS TO DISCUSS WITH A CLINICIAN');if(selected.some(r=>r.conflicts?.length))lines.push('• Which source date or metadata should be verified against the original?');if(selected.some(r=>r.ocr&&!r.ocr.verified))lines.push('• Can the original handwritten source be reviewed to verify the uncertain text?');lines.push('• Is any information missing from the source documents?');lines.push('','This summary reproduces synthetic source text for discussion. It does not provide a diagnosis or treatment recommendation.');return lines.join('\n')}
function visitView(){const draft=state.visitDraft||buildVisitSummary();return `${heading('PREPARE FOR A CONVERSATION','Visit preparation','Create an editable, factual summary from records you select. Each item keeps its source ID, dates, provider, and any uncertainty.',`<button class="btn" data-action="export-visit">⇩ Export summary</button><button class="btn btn-primary" data-action="print-visit">Print</button>`)}<div class="split-layout"><section class="card"><div class="card-header"><div><h2>Choose source records</h2><p>No diagnosis or treatment advice is generated.</p></div><button class="link-button" data-action="select-all-visit">Select all</button></div><div class="card-body selectable-list">${state.records.map(r=>`<label class="selectable-row"><input type="checkbox" data-visit-record="${r.id}" ${state.visitSelection.has(r.id)?'checked':''}><div><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.id)} · ${escapeHtml(r.provider)} · Event ${date(r.eventDate)}</small></div>${r.conflicts?.length?badge('Verify','amber'):badge('Source','teal')}</label>`).join('')}<button class="btn btn-primary" data-action="generate-visit" style="margin-top:9px">Generate factual summary</button></div></section><section class="card"><div class="card-header"><div><h2>Editable summary</h2><p>Text is synthetic and stays in this browser demo.</p></div>${badge('SOURCE-LINKED','blue')}</div><div class="card-body"><textarea id="visitDraft" aria-label="Editable synthetic visit summary" style="width:100%;min-height:430px;background:#edf4f2;color:#19343a;border:0;border-radius:10px;padding:14px;font:10px/1.65 'DM Sans',sans-serif;resize:vertical">${escapeHtml(draft)}</textarea><p class="subtle-note">Record IDs link to the synthetic source library. Please verify source details with a clinician.</p></div></section></div>`}

function scenarioCard([id,icon,title,description]){const result=state.scenarioResults[id];return `<article class="card scenario-card"><div class="scenario-card-top"><span class="scenario-icon">${icon}</span><div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(description)}</p></div></div>${result?`<div class="scenario-result">${escapeHtml(result.message)}${result.grant?.id?`<br><strong>Grant:</strong> ${escapeHtml(result.grant.id)} · <button class="link-button" data-nav="consent">Open consent center →</button>`:''}${result.error?`<br><button class="link-button" data-action="refresh-demo">Retry mock service</button>`:''}</div>`:''}<div class="scenario-card-actions"><span class="tiny muted">${result?date(result.at,{hour:'2-digit',minute:'2-digit'}):'Ready to run'}</span><button class="btn btn-sm ${id==='service-outage'?'':'btn-primary'}" data-scenario="${id}">${result?.error?'Retry':'Run scenario'} <span>→</span></button></div></article>`}
function scenariosView(){return `${heading('A DEMO YOU CAN DRIVE','Demo scenarios','Each scenario changes mock state and writes an audit event. Reset returns the app to its seeded fictional data.',`<button class="btn" data-action="reset-demo">↻ Reset demo</button>`)}<div class="scenario-grid">${scenarios.map(scenarioCard).join('')}</div><div class="section-title"><div><h2>Scripted edge cases</h2><p>${state.edgeCases.length} documented synthetic conditions</p></div></div><section class="card" style="padding:12px"><div class="edge-list">${state.edgeCases.map(([id,name,description])=>`<div class="edge-item"><strong>${escapeHtml(id)} · ${escapeHtml(name)}</strong><small>${escapeHtml(description)}</small></div>`).join('')}</div></section><div class="section-title"><div><h2>Acceptance test results</h2><p>Runs real service assertions against isolated synthetic state.</p></div><button class="btn btn-primary" data-action="run-tests">▶ Run 24 checks</button></div><section class="card" style="padding:14px" id="testResultsPanel">${state.testResults?renderTestResults(state.testResults):`<div class="empty-state" style="padding:20px"><strong>Not run in this session</strong>Run the checks to show actual pass and fail results from the mock service.</div>`}</section>`}
function renderTestResults(result){return `<div class="inline-actions" style="justify-content:space-between;margin-bottom:11px"><span class="integrity-status">Executed ${date(result.runAt,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span><span>${result.passed}/${result.total} passed ${result.failed?badge(`${result.failed} failed`,'red'):badge('All passed','teal')}</span></div><div class="test-results">${result.results.map(x=>`<div class="test-case ${x.passed?'pass':'fail'}">${escapeHtml(x.name)}${x.error?` — ${escapeHtml(x.error)}`:''}</div>`).join('')}</div>`}
function settingsView(){return `${heading('YOUR EXPERIENCE','Settings','Choose how the prototype behaves on this device. Preferences are local to this browser session.',`<button class="btn btn-danger" data-action="reset-demo">Reset synthetic data</button>`)}<div class="settings-grid"><section class="card"><div class="card-header"><div><h2>Accessibility & display</h2><p>Choose the presentation that works best for you.</p></div></div><div class="card-body"><div class="setting-row"><div><strong>Language</strong><small>English and key Telugu interface labels</small></div><button class="language-button" data-action="toggle-language">${state.language==='en'?'English · EN':'తెలుగు · TE'}</button></div><div class="setting-row"><div><strong>Reduced motion</strong><small>Reduce scene movement and interface transitions.</small></div><input type="checkbox" class="switch" data-setting="reducedMotion" ${state.reducedMotion?'checked':''} aria-label="Reduced motion"></div><div class="setting-row"><div><strong>2D accessible anatomy map</strong><small>Use keyboard-accessible record hotspots without WebGL.</small></div><input type="checkbox" class="switch" data-setting="force2d" ${state.force2d?'checked':''} aria-label="Use two dimensional anatomy fallback"></div><div class="setting-row"><div><strong>Compact navigation</strong><small>Collapse the left navigation rail.</small></div><button class="btn btn-sm" data-action="collapse-nav">${document.querySelector('.app-shell').classList.contains('collapsed')?'Expand':'Collapse'} navigation</button></div></div></section><section class="card"><div class="card-header"><div><h2>Privacy & demo data</h2><p>No real healthcare services are connected.</p></div></div><div class="card-body"><div class="setting-row"><div><strong>Data mode</strong><small>Seeded fictional records, local mock APIs, browser-only state.</small></div>${badge('SYNTHETIC','teal')}</div><div class="setting-row"><div><strong>Reset demo workspace</strong><small>Restore the original sample records and seven-day consent.</small></div><button class="btn btn-sm btn-danger" data-action="reset-demo">Reset</button></div><div class="setting-row"><div><strong>Export synthetic data</strong><small>Download a JSON snapshot of current demo state.</small></div><button class="btn btn-sm" data-action="export-data">Download JSON</button></div><div class="setting-row"><div><strong>Audit integrity check</strong><small>Verify the local hash-linked event chain.</small></div><button class="btn btn-sm" data-action="audit-check">Verify now</button></div><p class="subtle-note">The local event ledger demonstrates integrity checks only. It is not a secure production audit system. Revoking simulated access cannot recall copies already downloaded by a recipient.</p></div></section></div>`}

function bindScene(){if(state.view!=='overview')return;const canvas=document.querySelector('#healthScene');const fallback=document.querySelector('#sceneFallback');if(!canvas||!fallback)return;const records=state.records.map(r=>({id:r.id,provider:r.provider,category:r.category,title:r.title}));state.sceneCleanup=mountHealthScene(canvas,{records,provider:state.selectedProvider,reducedMotion:state.reducedMotion,force2d:state.force2d,onSelect:openRecord,onFallback:(enabled)=>{fallback.style.display=enabled?'flex':'none';canvas.style.display=enabled?'none':'block';}});}
function showModal(title,subtitle,content,footer='',wide=false){modalRoot.innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><h2 id="modalTitle">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button close-modal" data-action="close-modal" aria-label="Close dialog">×</button></header><div class="modal-content">${content}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;setTimeout(()=>modalRoot.querySelector('button,input,select,textarea')?.focus(),0);}
function closeModal(){modalRoot.innerHTML='';}
function historyMarkup(r){return (r.history||[]).slice().reverse().map(h=>`<div class="history-item"><strong>${escapeHtml(h.kind)} · ${escapeHtml(h.author)} · ${date(h.timestamp)}</strong><small>${escapeHtml(h.reason||'Review event')}${h.changes?`<br>${escapeHtml(Object.keys(h.changes).map(k=>`${k}: ${h.changes[k].before} → ${h.changes[k].after}`).join(' · '))}`:''}</small></div>`).join('')||`<p class="subtle-note">No additional history for this synthetic record.</p>`}
async function openRecord(id){state.activeRecordId=id;try{const r=await api(`/api/records/${encodeURIComponent(id)}`);const fields=[['Event date',date(r.eventDate)],['Report date',date(r.reportDate)],['Upload date',date(r.uploadDate)],['Provider',r.provider||'Missing'],['Location',r.location||'Missing'],['Source',r.source],['Provenance',r.provenance],['Verification',r.verification],['Sharing status',r.sharing],['Record version',String(r.version)]];showModal(escapeHtml(r.title),`${escapeHtml(r.id)} · ${escapeHtml(r.category)}`,`<div class="detail-hero"><span class="record-icon">${categoryIcon[r.category]||'▤'}</span><div><div class="detail-id">${escapeHtml(r.type)}</div><div class="detail-title">${escapeHtml(r.title)}</div><div class="detail-sub">${escapeHtml(r.provider||'Provider missing')} · ${escapeHtml(r.location||'Location not supplied')}</div></div>${r.conflicts?.length?badge('Review needed','amber'):badge('Source recorded','teal')}</div><div class="divider"></div><div class="info-grid">${fields.map(([k,v])=>`<div class="info-tile"><small>${escapeHtml(k)}</small><strong>${escapeHtml(v)}</strong></div>`).join('')}</div><div class="section-title"><div><h2>Source-reported content</h2></div></div><div class="consent-note">${escapeHtml(r.values||'No source text supplied.')}</div>${r.ocr?`<div class="warning-box" style="margin-top:10px"><strong>Uncertain OCR · ${Math.round(r.ocr.confidence*100)}% confidence</strong><br>Text: “${escapeHtml(r.ocr.text)}” · ${r.ocr.verified?'human verified':'not verified'}<br>This field is not a confirmed medical instruction.</div>`:''}${r.correction?`<div class="warning-box" style="margin-top:10px">Correction assertion: ${escapeHtml(r.correction.field)} → ${escapeHtml(r.correction.value)} · ${escapeHtml(r.correction.reason)}<br>Linked original: ${escapeHtml(r.supersedes)}</div>`:''}${r.possibleDuplicateOf?`<p class="subtle-note" style="margin-top:10px">Linked as a possible duplicate of ${escapeHtml(r.possibleDuplicateOf)}. Neither record was merged or deleted.</p>`:''}<div class="section-title"><div><h2>Record history</h2></div></div>${historyMarkup(r)}`,`<button class="btn" data-action="close-modal">Close</button><button class="btn" data-action="flag-current-record">Flag for review</button><button class="btn" data-action="edit-record" data-record="${r.id}">Edit metadata</button><button class="btn btn-primary" data-action="open-correction" data-record="${r.id}">Add correction assertion</button>`,true);}catch(err){toast(formatError(err),'error');}}
async function openEditRecord(id){closeModal();const r=state.records.find(x=>x.id===id);if(!r)return;showModal('Edit record metadata',`${r.id} · Changes create an attributed assertion; original source stays available.`, `<form id="recordEditForm" class="form-grid"><input type="hidden" name="id" value="${r.id}"><input type="hidden" name="expectedVersion" value="${r.version}"><div class="field"><label>Title</label><input name="title" value="${escapeHtml(r.title)}" required maxlength="100"></div><div class="field"><label>Provider</label><input name="provider" value="${escapeHtml(r.provider)}" required maxlength="100"></div><div class="field"><label>Event date</label><input type="date" name="eventDate" value="${escapeHtml(r.eventDate)}" required></div><div class="field"><label>Report date</label><input type="date" name="reportDate" value="${escapeHtml(r.reportDate)}"></div><div class="field"><label>Location</label><input name="location" value="${escapeHtml(r.location)}"></div><div class="field"><label>Source label</label><input name="source" value="${escapeHtml(r.source)}"></div><div class="field span-2"><label>Reason for metadata assertion</label><textarea name="reason" required placeholder="Describe what source was checked and why this field needs an assertion."></textarea></div><div class="field span-2"><small class="field-help">This edits display metadata in the demo. For a medical correction, create a separate linked correction assertion instead.</small></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-form" data-form="recordEditForm">Save metadata assertion</button>`);}
function openNewRecord(){showModal('Add a synthetic record','Every entry is fictional and locally stored for this demo.',`<form id="newRecordForm" class="form-grid"><div class="field"><label>Record title</label><input name="title" required maxlength="100" placeholder="e.g. Follow-up report"></div><div class="field"><label>Category</label><select name="category" required><option value="">Choose category</option>${categoryOptions.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Fictional provider</label><input name="provider" required maxlength="100" placeholder="Demo provider name"></div><div class="field"><label>Event date</label><input type="date" name="eventDate" required></div><div class="field"><label>Report date</label><input type="date" name="reportDate"></div><div class="field"><label>Location</label><input name="location" placeholder="Optional location"></div><div class="field span-2"><label>Source-reported note</label><textarea name="values" maxlength="500" placeholder="Synthetic source description; no real medical details."></textarea></div><div class="field span-2"><div class="warning-box">Do not enter real health information. The local mock API validates and stores synthetic demo records only.</div></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-form" data-form="newRecordForm">Save synthetic record</button>`);}
function openCorrection(id){const r=state.records.find(x=>x.id===id);if(!r)return;closeModal();showModal('Create a correction assertion',`This adds a linked version for ${r.id}; the original source remains preserved.`, `<form id="correctionForm" class="form-grid"><input type="hidden" name="id" value="${r.id}"><div class="field"><label>Field reviewed</label><select name="field" required><option value="eventDate">Event date</option><option value="reportDate">Report date</option><option value="provider">Provider</option><option value="location">Location</option><option value="title">Record title</option><option value="source">Source label</option><option value="other">Other metadata</option></select></div><div class="field"><label>Corrected assertion</label><input name="value" required maxlength="160" placeholder="Value to record for human review"></div><div class="field span-2"><label>Reason and source for review</label><textarea name="reason" required minlength="5" placeholder="Describe what was reviewed; do not claim external delivery."></textarea></div><div class="field span-2"><div class="warning-box">A correction is an attributed assertion in this demo, not a medical judgment. Active shares will be identified and the recipient preview will show a notice.</div></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-form" data-form="correctionForm">Create linked correction</button>`);}
function openCaregiverEdit(id){const c=state.caregivers.find(x=>x.permissions.some(p=>p.id===id));const grant=c?.permissions.find(p=>p.id===id);if(!grant)return;const days=Math.max(1,Math.ceil((new Date(grant.expiresAt)-Date.now())/86400000));showModal('Modify caregiver permission',`${c.name} · changes apply to this scoped grant`, `<form id="caregiverEditForm"><input type="hidden" name="id" value="${escapeHtml(id)}"><div class="field"><label>Allowed actions</label>${[['view_selected_records','View selected records'],['review_appointments','Review appointments'],['prepare_visit_summary','Prepare a visit summary'],['manage_admin_tasks','Manage administrative tasks']].map(([value,label])=>`<label class="permission-row"><input type="checkbox" name="actions" value="${value}" ${grant.actions.includes(value)?'checked':''}> <span class="subtle-note">${label}</span></label>`).join('')}</div><div class="field" style="margin-top:12px"><label>Allowed record categories</label><div class="checkbox-list" style="display:grid;grid-template-columns:1fr 1fr">${categoryOptions.map(c=>`<label class="checkbox-option"><input type="checkbox" name="categories" value="${escapeHtml(c)}" ${grant.categories.includes(c)?'checked':''}>${escapeHtml(c)}</label>`).join('')}</div><small class="field-help">Record viewing and visit-summary actions require at least one selected category.</small></div><div class="field" style="margin-top:12px"><label>Duration from now</label><select name="durationDays"><option value="1" ${days<=1?'selected':''}>1 day</option><option value="7" ${days>1&&days<=7?'selected':''}>7 days</option><option value="30" ${days>7&&days<=30?'selected':''}>30 days</option><option value="90" ${days>30?'selected':''}>90 days</option></select></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-form" data-form="caregiverEditForm">Save permission changes</button>`);}
function openFlagRecord(id){showModal('Flag a record for human review',`${id} · this adds an audit event and a record-history note.`, `<form id="flagConflictForm"><input type="hidden" name="recordId" value="${escapeHtml(id)}"><div class="field"><label>Reason for review</label><textarea name="reason" required minlength="5" maxlength="300" placeholder="Explain what source information needs review."></textarea></div><p class="subtle-note">A flag records uncertainty; it does not change source values or decide which value is correct.</p></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-form" data-form="flagConflictForm">Add review flag</button>`);}
function shareReceipt(g){showModal('Simulated share receipt',`${g.id} · No external provider has received or acknowledged this data.`,`<div class="warning-box" style="margin-bottom:12px">This is a local demo grant. It enforces the selected record scope and expiry inside the mock API.</div><div class="info-grid"><div class="info-tile"><small>Recipient</small><strong>${escapeHtml(g.recipient)}</strong></div><div class="info-tile"><small>Purpose</small><strong>${escapeHtml(g.purpose)}</strong></div><div class="info-tile"><small>Expires</small><strong>${date(g.expiresAt)}</strong></div></div><div class="section-title"><div><h2>Scope</h2></div></div><div class="pill-list">${g.recordIds.map(id=>{const r=state.records.find(x=>x.id===id);return `<span class="pill">${escapeHtml(r?.title||id)}</span>`}).join('')}${g.categories.map(c=>`<span class="pill">${escapeHtml(c)}</span>`).join('')||''}</div><p class="subtle-note" style="margin-top:12px">Recipient access remains bounded by this purpose and expiry. Revoking blocks later simulated reads. A revocation cannot guarantee deletion of copies already downloaded.</p>`,`<button class="btn" data-action="close-modal">Done</button><button class="btn" data-action="recipient-view" data-grant="${g.id}">Open recipient view</button>`,false);}
async function recipientView(id){try{const data=await api(`/api/recipient/${encodeURIComponent(id)}/records`);showModal('Simulated recipient view',`Visible only within ${escapeHtml(data.grant.id)} · ${escapeHtml(data.purpose)}`,`<div class="warning-box" style="margin-bottom:12px">This preview enforces the local share scope. It does not indicate delivery, receipt, or acknowledgement by a real provider.</div>${data.correctionNotices.length?`<div class="alert-strip"><span class="alert-icon">⟲</span><div><strong>Correction notice</strong><span>${data.correctionNotices.map(x=>`${escapeHtml(x.original)} → ${escapeHtml(x.correction)} · ${escapeHtml(x.notice)}`).join('<br>')}</span></div></div>`:''}<div class="record-list">${data.records.map(recordRow).join('')||`<div class="empty-state"><strong>No records in scope</strong></div>`}</div><p class="subtle-note">Recipient read attempt added to the audit trail.</p>`,`<button class="btn" data-action="close-modal">Close</button>`,true);await loadAudit(false);}catch(err){toast(formatError(err),'error');await loadAudit(false);}}

function bindAfterRender(){if(state.view==='audit')loadAudit(false);if(state.view==='overview')bindScene();}
async function loadBootstrap(shouldRender=true){try{const [boot,dash]=await Promise.all([api('/api/bootstrap'),api('/api/dashboard')]);const apiProfile=boot.profile||{};const sessionProfile=Object.prototype.hasOwnProperty.call(apiProfile,'email')?null:readSessionProfile();state.profile={email:'',phone:'',dateOfBirth:'',...apiProfile,...(sessionProfile||{})};if(Object.prototype.hasOwnProperty.call(apiProfile,'email'))sessionStorage.removeItem(profileSessionKey);syncProfileChrome();state.records=boot.records;state.providers=boot.providers;state.grants=boot.grants;state.caregivers=boot.caregivers;state.notifications=boot.notifications;state.conflicts=boot.conflicts;state.edgeCases=boot.edgeCases;state.freshness=boot.freshness;state.demoState=boot.demoState;state.dashboard=dash;document.querySelector('#freshnessIndicator').textContent=boot.demoState.stale?'SOURCE SNAPSHOT · STALE':'LOCAL MOCK API · READY';if(shouldRender)render();}catch(error){main.innerHTML=`<section class="error-page"><h1>Could not load the local demo service</h1><p>${escapeHtml(formatError(error))}</p><button class="btn btn-primary" data-action="retry-bootstrap">Retry</button></section>`;}}
async function refreshState(){await loadBootstrap(false);if(state.view==='records')await refreshRecordData(false);if(state.view==='timeline')await refreshTimeline(false);if(state.view==='audit')await loadAudit(false);render();}
async function refreshRecordData(shouldRender=true){try{const params=new URLSearchParams();if(state.filters.search)params.set('search',state.filters.search);if(state.filters.category)params.set('category',state.filters.category);if(state.filters.provider)params.set('provider',state.filters.provider);if(state.filters.sort)params.set('sort',state.filters.sort);state.serverRecordResults=await api(`/api/records?${params}`);if(shouldRender)render();}catch(err){toast(formatError(err),'error');}}
async function refreshTimeline(shouldRender=true){try{const params=new URLSearchParams();if(state.filters.provider)params.set('provider',state.filters.provider);if(state.filters.category)params.set('category',state.filters.category);state.timelineResults=await api(`/api/timeline?${params}`);if(shouldRender)render();}catch(err){toast(formatError(err),'error');}}
async function loadAudit(shouldRender=true){const list=document.querySelector('#auditList');if(list)list.innerHTML=`<div class="loading-state" style="min-height:90px"><span class="spinner"></span>Loading audit entries…</div>`;try{const data=await api(`/api/audit${state.auditSearch?`?search=${encodeURIComponent(state.auditSearch)}`:''}`);if(!document.querySelector('#auditList'))return;document.querySelector('#auditList').innerHTML=data.events.map(ev=>`<div class="audit-row"><time class="audit-time">${date(ev.timestamp,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}<br>${escapeHtml(ev.id)}</time><div class="audit-main"><strong>${escapeHtml(ev.action.replaceAll('_',' '))} · ${escapeHtml(ev.resource)}</strong><small>${escapeHtml(ev.reason||'No additional reason')}<br>Hash: <span title="${escapeHtml(ev.hash)}">${escapeHtml(ev.hash.slice(0,18))}…</span></small><div class="audit-actor">Actor · ${escapeHtml(ev.actor)}</div></div><div class="audit-outcome">${badge(ev.outcome,ev.outcome==='success'?'teal':ev.outcome==='blocked'||ev.outcome==='failed'?'red':'amber')}</div></div>`).join('')||`<div class="empty-state"><strong>No matching events</strong>Try a different search phrase.</div>`;document.querySelector('#auditCount').textContent=`${data.events.length} events`;document.querySelector('#integrityStatus').textContent=data.integrity.valid?`Hash chain verified · ${data.integrity.checked} events`:`Integrity issue at ${data.integrity.failedEventId}`;document.querySelector('#integrityStatus').style.color=data.integrity.valid?'#8fe0c9':'#f09ca5';}catch(err){if(list)list.innerHTML=`<div class="empty-state"><strong>Could not load the ledger</strong>${escapeHtml(formatError(err))}</div>`;}if(shouldRender&&state.view==='audit'){} }
function formObject(form){const data=new FormData(form);const out={};for(const [key,value] of data.entries()){if(out[key]===undefined)out[key]=value;else if(Array.isArray(out[key]))out[key].push(value);else out[key]=[out[key],value];}return out;}
function formList(form,key){return [...form.querySelectorAll(`[name="${key}"]:checked`)].map(x=>x.value)}
function updateSharePreview(){const form=document.querySelector('#shareForm');if(!form)return;const f=new FormData(form);const recipient=f.get('recipient')||'Not selected';document.querySelector('#previewRecipient').textContent=recipient==='Custom fictional recipient'?'Custom fictional recipient':recipient;document.querySelector('#previewPurpose').textContent=f.get('purpose')||'Not selected';const days=Number(f.get('expirationDays')||7);document.querySelector('#previewExpiry').textContent=`${days} day${days===1?'':'s'} from confirmation`;const ids=formList(form,'recordIds'),categories=formList(form,'categories');const chosen=state.records.filter(r=>ids.includes(r.id)||categories.includes(r.category));document.querySelector('#previewRecords').innerHTML=chosen.length?chosen.map(r=>`<li>${escapeHtml(r.title)} · ${escapeHtml(r.id)}</li>`).join(''):`<li>Choose one or more records to preview.</li>`;}
function fileDownload(filename,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmReset(){showModal('Reset the demo workspace?','This restores the seeded fictional records and clears current simulated grants and audit history.',`<div class="warning-box">This demo action only resets local synthetic state. It does not affect any real account or healthcare record.</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-reset">Reset synthetic demo</button>`)}

document.addEventListener('click',async(event)=>{
  const nav=event.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);if(state.view==='records')refreshRecordData(true);if(state.view==='timeline')refreshTimeline(true);return;}
  const fallbackNode=event.target.closest('[data-record]');if(fallbackNode&&!event.target.closest('[data-record-edit]')&&!event.target.closest('[data-action]')){const id=fallbackNode.dataset.record;if(id)openRecord(id);return;}
  const edit=event.target.closest('[data-record-edit]');if(edit){openEditRecord(edit.dataset.record);return;}
  const scenario=event.target.closest('[data-scenario]');if(scenario){await runScenario(scenario.dataset.scenario);return;}
  const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
  try{
    if(action==='close-modal'){closeModal();return;}
    if(action==='new-record'){openNewRecord();return;}
    if(action==='edit-record'){openEditRecord(event.target.closest('[data-record]')?.dataset.record||event.target.closest('[data-action]')?.dataset.record);return;}
    if(action==='open-correction'){openCorrection(event.target.closest('[data-action]')?.dataset.record);return;}
    if(action==='flag-record'){openFlagRecord(event.target.closest('[data-record]')?.dataset.record||event.target.closest('[data-action]')?.dataset.record);return;}
    if(action==='flag-current-record'){openFlagRecord(state.activeRecordId);return;}
    if(action==='open-conflict-source'){openRecord(event.target.closest('[data-action]')?.dataset.record);return;}
    if(action==='edit-caregiver'){openCaregiverEdit(event.target.closest('[data-grant]').dataset.grant);return;}
    if(action==='submit-form'){const form=document.getElementById(event.target.closest('[data-action]').dataset.form);form?.requestSubmit();return;}
    if(action==='clear-record-filters'){state.filters={search:'',category:'',provider:'',sort:'newest'};state.page=1;state.serverRecordResults=null;await refreshRecordData();return;}
    if(action==='clear-timeline-filters'){state.filters.provider='';state.filters.category='';state.timelineResults=null;await refreshTimeline();return;}
    if(action==='page-next'){state.page++;render();return;}if(action==='page-prev'){state.page=Math.max(1,state.page-1);render();return;}
    if(action==='provider-select'){state.selectedProvider=event.target.closest('[data-provider]').dataset.provider;render();return;}
    if(action==='conflict-retain'){const result=await api('/api/scenarios/action',{method:'POST',body:JSON.stringify({action:'mark-date-reviewed'})});await refreshState();toast('Both synthetic reports retained. Date correctness remains unresolved.');return;}
    if(action==='conflict-link'){const result=await api('/api/scenarios/action',{method:'POST',body:JSON.stringify({action:'link-records',payload:{recordIds:['HV-LAB-1042','HV-LAB-1098']}})});await refreshState();toast('Linked as a possible duplicate. Both records are preserved.');return;}
    if(action==='verify-ocr'){await api('/api/scenarios/action',{method:'POST',body:JSON.stringify({action:'verify-ocr'})});await refreshState();toast('Human review requested; uncertain text remains unconfirmed.');return;}
    if(action==='refresh-conflicts'){state.conflicts=await api('/api/conflicts');render();toast('Conflict flags refreshed from the local mock API.');return;}
    if(action==='recipient-view'){const id=event.target.closest('[data-grant]').dataset.grant;await recipientView(id);return;}
    if(action==='revoke-share'){const id=event.target.closest('[data-grant]').dataset.grant;if(!window.confirm('Revoke this simulated share? Later demo access will be blocked.'))return;const g=await api(`/api/grants/${encodeURIComponent(id)}`,{method:'DELETE'});await refreshState();toast('Share revoked. Later simulated access will be blocked. Downloaded copies cannot be recalled.');return;}
    if(action==='revoke-caregiver'){const id=event.target.closest('[data-grant]').dataset.grant;const g=await api(`/api/caregivers/grants/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({revoke:true})});await refreshState();toast('Caregiver permission revoked.');return;}
    if(action==='caregiver-attempt'){const c=state.caregivers[0];const result=await api('/api/caregivers/attempt',{method:'POST',body:JSON.stringify({caregiverId:c.id,grantId:c.permissions.find(p=>p.status==='active')?.id,action:'view_selected_records',category:'Consultation notes',resource:'HV-CNS-3304'})});toast(result.message||'Caregiver request completed.');await refreshState();return;}
    if(action==='revoke-emergency'){const id=event.target.closest('[data-grant]').dataset.grant;await api(`/api/emergency/${encodeURIComponent(id)}`,{method:'DELETE'});state.currentEmergency={...state.currentEmergency,status:'revoked'};render();toast('Simulated emergency access revoked.');await loadAudit(false);return;}
    if(action==='audit-check'){const r=await api('/api/audit');const integrity=r.integrity;if(integrity.valid)toast(`Hash chain verified across ${integrity.checked} events.`);else toast(`Hash mismatch found at ${integrity.failedEventId}.`,'error');const el=document.querySelector('#integrityStatus');if(el)el.textContent=integrity.valid?`Hash chain verified · ${integrity.checked} events`:`Integrity issue at ${integrity.failedEventId}`;return;}
    if(action==='audit-clear'){state.auditSearch='';document.querySelector('#auditSearch').value='';await loadAudit(false);return;}
    if(action==='toggle-language'){state.language=state.language==='en'?'te':'en';document.querySelector('#languageToggle').textContent=state.language==='en'?'తెలుగు':'English';render();return;}
    if(action==='collapse-nav'){document.querySelector('.app-shell').classList.toggle('collapsed');render();return;}
    if(action==='shuffle-demo-vitals'){state.demoVitals=generateDemoVitals();render();toast('New fictional demo readings generated.');return;}
    if(action==='refresh-demo'){await api('/api/scenarios/refresh',{method:'POST',body:'{}'});state.scenarioResults['service-outage']={message:'Mock API recovered. Saved synthetic records are intact.',at:new Date().toISOString()};await refreshState();toast('Mock service refreshed; saved demo state is intact.');return;}
    if(action==='reset-demo'){confirmReset();return;}
    if(action==='confirm-reset'){await api('/api/scenarios/run',{method:'POST',body:JSON.stringify({id:'reset'})});state.scenarioResults={};state.visitSelection.clear();state.visitDraft='';state.currentEmergency=null;state.filters={search:'',category:'',provider:'',sort:'newest'};state.testResults=null;sessionStorage.removeItem(profileSessionKey);closeModal();await refreshState();toast('Demo restored to its seeded synthetic state.');return;}
    if(action==='run-tests'){const r=await api('/api/demo-tests',{method:'POST',body:'{}'});state.testResults=r;render();toast(`${r.passed} of ${r.total} acceptance checks passed${r.failed?`; ${r.failed} failed`:''}.`,r.failed?'error':'success');return;}
    if(action==='select-all-visit'){state.visitSelection=new Set(state.records.map(r=>r.id));state.visitDraft=buildVisitSummary();render();return;}
    if(action==='generate-visit'){state.visitDraft=buildVisitSummary();render();toast('Factual synthetic summary generated with source references.');return;}
    if(action==='export-visit'){const text=document.querySelector('#visitDraft')?.value||state.visitDraft||buildVisitSummary();state.visitDraft=text;fileDownload('viba-synthetic-visit-summary.txt',text);toast('Synthetic visit summary exported.');return;}
    if(action==='print-visit'){const content=document.querySelector('#visitDraft')?.value||state.visitDraft||buildVisitSummary();state.visitDraft=content;const win=window.open('','_blank');if(!win){toast('Allow a new tab to print this synthetic summary.','error');return;}win.document.write(`<!doctype html><title>VIBA — ABHA redefined....! — synthetic visit summary</title><pre style="font:12px/1.6 sans-serif;white-space:pre-wrap;max-width:760px;margin:32px auto">${escapeHtml(content)}</pre><script>window.print()<\/script>`);win.document.close();return;}
    if(action==='export-data'){const ledger=await api('/api/audit');const data={synthetic:true,profile:state.profile,records:state.records,grants:state.grants,caregivers:state.caregivers,audit:ledger.events};fileDownload('viba-synthetic-demo.json',JSON.stringify(data,null,2),'application/json');toast('Synthetic demo snapshot downloaded.');return;}
  }catch(error){toast(formatError(error),'error');if(['audit-check','revoke-share','recipient-view','caregiver-attempt'].includes(action))await loadAudit(false);}
});

document.addEventListener('click',(event)=>{const button=event.target.closest('[data-chat-prompt]');if(!button)return;const form=document.querySelector('#aiChatForm');if(form){form.elements.message.value=button.dataset.chatPrompt;form.requestSubmit();}});
document.addEventListener('submit',async(event)=>{const form=event.target;if(form?.id!=='profileForm')return;event.preventDefault();try{const result=await saveProfileDetails(formObject(form));state.profile=result.profile;syncProfileChrome(result.profile);render();toast(result.localOnly?'Profile details saved for this browser session.':'Profile details saved to this local demo.');}catch(error){toast(formatError(error),'error');}});
document.addEventListener('submit',async(event)=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(form.id==='aiChatForm'){const text=form.elements.message.value.trim();if(!text)return;appendAssistantConversation(state,text);render();document.querySelector('#aiChatInput')?.focus();return;}try{
  if(form.id==='shareForm'){const recipient=form.elements.recipient.value;if(recipient==='Custom fictional recipient'){toast('Choose one of the provided fictional recipients.','error');return;}const payload={recipient,recipientType:form.elements.recipientType.value,purpose:form.elements.purpose.value.trim(),expirationDays:Number(form.elements.expirationDays.value),recordIds:formList(form,'recordIds'),categories:formList(form,'categories')};const grant=await api('/api/grants',{method:'POST',body:JSON.stringify(payload)});closeModal();await refreshState();shareReceipt(grant);toast('Simulated consent grant created.');return;}
  if(form.id==='caregiverForm'){const payload={caregiverId:form.elements.caregiverId.value,actions:formList(form,'actions'),categories:formList(form,'categories'),durationDays:Number(form.elements.durationDays.value)};const grant=await api('/api/caregivers/grants',{method:'POST',body:JSON.stringify(payload)});await refreshState();toast('Scoped caregiver permission created.');return;}
  if(form.id==='caregiverEditForm'){const payload={actions:formList(form,'actions'),categories:formList(form,'categories'),durationDays:Number(form.elements.durationDays.value)};const id=form.elements.id.value;await api(`/api/caregivers/grants/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(payload)});closeModal();await refreshState();toast('Caregiver permission scope updated.');return;}
  if(form.id==='flagConflictForm'){const payload=formObject(form);const result=await api('/api/scenarios/action',{method:'POST',body:JSON.stringify({action:'flag-record-conflict',payload})});closeModal();await refreshState();toast('Record flagged for human source review.');return;}
  if(form.id==='emergencyForm'){const payload=formObject(form);payload.confirmed=form.elements.confirmed.checked;const grant=await api('/api/emergency/access',{method:'POST',body:JSON.stringify(payload)});state.currentEmergency=grant;form.reset();await refreshState();toast('Simulated limited emergency grant created and logged.');return;}
  if(form.id==='newRecordForm'){const payload=formObject(form);const record=await api('/api/records',{method:'POST',body:JSON.stringify(payload)});closeModal();state.page=1;await refreshState();toast(`Synthetic record ${record.id} added.`);return;}
  if(form.id==='recordEditForm'){const payload=formObject(form);const id=payload.id;delete payload.id;payload.expectedVersion=Number(payload.expectedVersion);const record=await api(`/api/records/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(payload)});closeModal();await refreshState();toast('Metadata assertion saved with its source reason.');return;}
  if(form.id==='correctionForm'){const payload=formObject(form);const id=payload.id;delete payload.id;const result=await api(`/api/records/${encodeURIComponent(id)}/corrections`,{method:'POST',body:JSON.stringify(payload)});closeModal();await refreshState();showModal('Correction assertion recorded',`${result.correction.id} · original remains preserved`,`<div class="info-grid"><div class="info-tile"><small>Original</small><strong>${escapeHtml(result.original.id)} · preserved</strong></div><div class="info-tile"><small>Correction</small><strong>${escapeHtml(result.correction.id)}</strong></div><div class="info-tile"><small>Affected active shares</small><strong>${result.affectedShares.length}</strong></div></div><div class="warning-box" style="margin-top:12px">${escapeHtml(result.recipientNotice)}</div>${result.affectedShares.map(x=>`<div class="history-item"><strong>${escapeHtml(x.recipient)}</strong><small>${escapeHtml(x.grantId)} · ${escapeHtml(x.status)}</small></div>`).join('')}`,`<button class="btn" data-action="close-modal">Done</button>`,false);toast('Linked correction assertion created; original preserved.');return;}
}catch(error){toast(formatError(error),'error');if(error.code==='CONFLICT'){showModal('Edit conflict','The mock API rejected this stale edit. No source value was overwritten.','<div class=""warning-box"">Review the current version before retrying.</div>','<button class=""btn"" data-action=""close-modal"">Close</button>');}}});

document.addEventListener('input',(event)=>{const el=event.target;if(el.id==='shareForm'||el.closest?.('#shareForm'))updateSharePreview();if(el.id==='visitDraft')state.visitDraft=el.value;if(el.id==='recordSearch'){state.filters.search=el.value;state.page=1;clearTimeout(window.__recordSearchTimer);window.__recordSearchTimer=setTimeout(()=>refreshRecordData(),180);}if(el.id==='auditSearch'){state.auditSearch=el.value;clearTimeout(window.__auditSearchTimer);window.__auditSearchTimer=setTimeout(()=>loadAudit(false),180);}if(el.id==='globalSearch'){state.globalQuery=el.value;renderGlobalSearch();}});
document.addEventListener('change',async(event)=>{const el=event.target;if(el.id==='shareForm'||el.closest?.('#shareForm'))updateSharePreview();if(el.id==='recordCategory'){state.filters.category=el.value;state.page=1;await refreshRecordData();}if(el.id==='recordProvider'){state.filters.provider=el.value;state.page=1;await refreshRecordData();}if(el.id==='recordSort'){state.filters.sort=el.value;state.page=1;await refreshRecordData();}if(el.id==='timelineProvider'){state.filters.provider=el.value;await refreshTimeline();}if(el.id==='timelineCategory'){state.filters.category=el.value;state.timelineResults=null;render();await refreshTimeline();}if(el.dataset.visitRecord!==undefined){if(el.checked)state.visitSelection.add(el.dataset.visitRecord);else state.visitSelection.delete(el.dataset.visitRecord);state.visitDraft='';}if(el.dataset.setting){state[el.dataset.setting]=el.checked;render();}if(el.id==='providerSceneFilter'){state.selectedProvider=el.value;render();}});

document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&modalRoot.innerHTML){closeModal();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('#globalSearch').focus();}if(event.key==='Enter'&&event.target.matches('[data-record],[data-nav],.activity-item,.timeline-mini-item')){event.preventDefault();event.target.click();}});
document.querySelector('#collapseNav').addEventListener('click',()=>{document.querySelector('.app-shell').classList.toggle('collapsed');render();});
document.querySelector('#mobileMenu').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('mobile-open'));
document.querySelector('#languageToggle').addEventListener('click',()=>{state.language=state.language==='en'?'te':'en';document.querySelector('#languageToggle').textContent=state.language==='en'?'తెలుగు':'English';render();});
document.querySelector('#notificationButton').addEventListener('click',()=>{const box=document.querySelector('#notificationPopover');if(!box.hidden){box.hidden=true;return;}box.innerHTML=`<h3>Notifications</h3>${state.notifications.map(n=>`<div class="notification-item"><strong>${escapeHtml(n.title)}</strong><p>${escapeHtml(n.body)}</p><small>${relative(n.time)}</small></div>`).join('')||`<div class="empty-state">No notifications.</div>`}`;box.hidden=false;});
function openProfileModal(){const p=state.profile||{};showModal('Fictional demo profile',p.label||'Synthetic account · no real patient identity',`<div class="detail-hero"><span class="avatar">${profileInitials(p.name)}</span><div><div class="detail-title">${escapeHtml(p.name||'Demo patient')}</div><div class="detail-sub">${escapeHtml(p.email||'Email not provided')} · ${escapeHtml(p.phone||'Phone not provided')}</div></div></div><div class="divider"></div><p class="subtle-note">Profile edits apply only to this fictional local demo and reset when the server restarts.</p>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn btn-primary" data-nav="settings">Edit profile details</button>`)}
document.querySelector('#profileButton').addEventListener('click',openProfileModal);
document.querySelector('#mainContent').addEventListener('click',()=>{});

async function runScenario(id){try{const result=await api('/api/scenarios/run',{method:'POST',body:JSON.stringify({id})});state.scenarioResults[id]={message:result.result||'Scenario completed.',at:new Date().toISOString(),grant:result.grant};await refreshState();if(id==='emergency-break-glass')state.currentEmergency=result.grant;if(id==='provider-correction')state.scenarioResults[id].message=result.result;if(id==='seven-day-share')state.scenarioResults[id].grant=result.grant;render();toast(result.result||'Scenario completed.');if(['conflicting-labs','uncertain-ocr','provider-correction','caregiver-boundary','emergency-break-glass'].includes(id)){if(id==='conflicting-labs')navigate('conflicts');if(id==='provider-correction')navigate('consent');if(id==='caregiver-boundary')navigate('caregivers');if(id==='emergency-break-glass')navigate('emergency');}}catch(error){state.scenarioResults[id]={message:formatError(error),error:true,at:new Date().toISOString()};render();toast(formatError(error),'error');}}

function renderGlobalSearch(){const input=document.querySelector('#globalSearch');let pop=input.parentElement.querySelector('.search-suggest');if(!pop){pop=document.createElement('div');pop.className='search-suggest';input.parentElement.append(pop);}const q=state.globalQuery.trim().toLowerCase();if(!q){pop.remove();return;}const records=state.records.filter(r=>`${r.id} ${r.title} ${r.provider} ${r.category}`.toLowerCase().includes(q)).slice(0,6);const providers=state.providers.filter(p=>p.name.toLowerCase().includes(q)).slice(0,3);pop.innerHTML=[...records.map(r=>`<div class="search-result" data-record="${r.id}" role="button" tabindex="0"><span><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.id)} · ${escapeHtml(r.provider)}</small></span>${badge('Record','blue')}</div>`),...providers.map(p=>`<div class="search-result" data-action="search-provider" data-provider="${escapeHtml(p.name)}" role="button" tabindex="0"><span><strong>${escapeHtml(p.name)}</strong><small>${p.connectedRecords} connected synthetic records</small></span>${badge('Provider','teal')}</div>`)].join('')||`<div class="empty-state" style="padding:15px">No matching synthetic records or providers.</div>`;}
document.querySelector('#globalSearch').addEventListener('keydown',(event)=>{if(event.key==='Enter'){event.preventDefault();if(state.globalQuery.trim()){state.filters.search=state.globalQuery.trim();navigate('records');refreshRecordData();document.querySelector('#globalSearch').blur();}}if(event.key==='Escape'){event.target.value='';state.globalQuery='';renderGlobalSearch();}});
document.addEventListener('click',(event)=>{const result=event.target.closest('.search-result[data-action="search-provider"]');if(result){state.selectedProvider=result.dataset.provider;state.filters.provider=result.dataset.provider;state.filters.search='';navigate('records');refreshRecordData();document.querySelector('#globalSearch').value='';document.querySelector('#globalSearch').parentElement.querySelector('.search-suggest')?.remove();return;}if(!event.target.closest('.global-search'))document.querySelector('#globalSearch').parentElement.querySelector('.search-suggest')?.remove();if(event.target.closest('[data-backdrop="true"]')&&event.target===event.target.closest('[data-backdrop="true"]'))closeModal();});

async function boot(){await loadBootstrap(false);await refreshRecordData(false);await refreshTimeline(false);render();}
boot();
